// 英文界面词典（设置 → 外观 → 语言 → English）。机制在 16-misc.js，这里只放词。
//
// 怎么查：整句当 key。界面上的文字节点 / placeholder / title / toast / 弹窗，
//   先按原样（去首尾空白）查 MAP；查不到再把中间的空白压成一个空格查一次；
//   再查不到就剥掉开头的 emoji / 符号和结尾的「：。！？…」只查中间那段
//   （「🗑 删除」「名称：」不用单独写 key，有「删除」「名称」就够）；
//   最后才走 RULES（带数字、名字插值的句子）。
//   ⚠️ 中文原文改了，这里的 key 要跟着改，不然英文界面就漏翻（settings-*-tab 测试守着几条）。
//
// 格式：MAP 一行一条 "中文":"English",（就是 JSON.stringify 的样子，测试按这个形状找），
//   MAP-BEGIN / MAP-END 中间去掉 // 注释行和结尾逗号必须是合法 JSON。不许重复 key、value 里不许有中文。
//   GranCyan-open 这份是从主仓的词典裁出来的：key 在 open 自己的源码里找不到的（open 没有的功能）整条拿掉，
//   tests/i18n-en.test.js 的 [1c] 守着。从主仓同步新词条时用 scripts/i18n-open-prune.js 裁一遍，不能整份拷。
