"小提示：别盲信我，我的逻辑偶尔也会离家出走(ง ᵒ̌皿ᵒ̌)ง":"Tip: don't blindly trust me — my logic sometimes runs away from home (ง ᵒ̌皿ᵒ̌)ง",
