"警告：此 AI 偶尔会产生幻觉，请携带常识阅读( ﾟ∀ﾟ)つ":"Warning: this AI occasionally hallucinates — please read with common sense ( ﾟ∀ﾟ)つ",
"我的大脑由算法构成，算法偶尔也会打结，记得帮我检查(ノ_<)":"My brain is made of algorithms, and algorithms sometimes tangle — remember to check me (ノ_<)",
"要是发现我哪里说错了，别客气，直接纠正我！(๑•̀ㅂ•́)و✧":"If you catch me getting something wrong, don't hesitate — just correct me! (๑•̀ㅂ•́)و✧",
"重要公式和数据请务必亲自验证，AI 概不报销打错的算盘~":"Please verify important formulas and data yourself; the AI won't reimburse a miscalculation~",
