"今日小票、小月历、纪念日卡、约定清单。小票它能帮你记（会标明是它记的），纪念日当天它会写一张卡，一年一张；它答应你的具体的事会记进约定清单，到日子自己提":"Today's receipt, mini calendar, anniversary card, promise list. It can log receipts for you (marked as logged by it), writes a card on each anniversary, one a year; and specific things it promises you go into the promise list, which it brings up itself when the day comes",
