"打开等于把「这次第几天 / 大概什么时候来」这类信息写进每轮提示词发给模型，关掉之后面板照用，只是它不知道":"When on, info like \"which day this is / roughly when it will come\" is written into every turn's prompt and sent to the model. When off, the panel still works, the model just doesn't know",
"这几样只存在这台设备上":"These only live on this device",
"小票、月历、纪念日卡和约定都不走云同步，换设备不会跟过去。（月历属于身体记录，默认不往云端传；要同步跟克克说一声":"Receipts, the calendar, anniversary cards and promises don't use cloud sync, so they won't follow you to another device. (The calendar counts as body records and isn't sent to the cloud by default; tell Keke if you want it synced",
"生活三件套":"Life trio",
"让它知道月历（会发给模型":"Let it know the calendar (sent to the model",
"共读同步 (Co-reading":"Co-reading sync (Co-reading",
"把伴读书架里的痕迹递到对话这边：在读哪本书、读到第几章、你和它最近各自划了什么线。开着的时候它在聊天里就知道书上发生过什么，不用你复述一遍。需要连着电脑上的 server.js；连不上就自动当没有，不会拖慢发消息":"Passes traces from the reading-companion bookshelf over to the chat: which book you're reading, which chapter you're on, and what each of you has recently underlined. While on, it knows in chat what has happened in the book, so you don't have to recap. Needs a connection to server.js on your computer; if it can't connect it's treated as absent and won't slow down sending",
"让对话看得见书架":"Let chat see the bookshelf",
"当前状态":"Current status",
"立刻同步一次":"Sync now",
"表情包 (Stickers / GIF":"Stickers (Stickers / GIF",
"指尖节奏":"Typing rhythm",
"让 AI 感觉到你打字时的停顿——这条打了多久、中途犹豫了几次、以及打了一段最后没发出来。默认只记时间，一个字都不碰":"Lets the AI feel the pauses while you type: how long this one took, how many times you hesitated midway, and a draft you typed but never sent. By default only timing is recorded, not a single character",
"开启指尖节奏（默认开启，只记节奏不记内容":"Turn on typing rhythm (on by default, records rhythm only, not content",
"连没发出去的草稿内容也让 AI 看到（默认关闭；开启后草稿原文会随请求发给模型":"Let the AI see even the content of unsent drafts (off by default; when on, the draft text is sent to the model with the request",
"书架里还没有书":"No books on the shelf yet",
"技能开关（省 token":"Skill switches (save tokens",
"每个技能都是一段常驻的系统提示":"Every skill is a resident system prompt",
"不管用不用，每一轮都要重新付一次钱":"whether it's used or not, you pay for it again every turn",
"和聊天历史不一样——历史长了还有裁剪兜着，这些是雷打不动的固定开销。 用不上的关掉即可，关掉后 AI 就不知道有这个能力了（已经存下的内容不受影响":"Unlike chat history, which has trimming as a safety net when it gets long, these are fixed costs that never budge. Turn off what you don't use, and the AI won't know it has that ability (content already saved isn't affected",
