"AI 在聊天里写 [[TASK: …]]，就能把查资料、核对、翻译这类杂活派给便宜模型在后台做，它自己照常陪你说话；结果搭着你下一条消息一起回到它眼前。要不要教它这招在「技能开关」里关":"When the AI writes [[TASK: …]] in chat, it can hand chores like looking things up, checking and translating to a cheaper model in the background while it keeps chatting with you as usual; the result comes back to it along with your next message. Whether to teach it this trick is switched off under \"Skill switches\"",
