"[[SIM]] 讲物理/化学时递一张 PhET 交互实验卡（抛体、电路、分子形状……），她点开能自己调参数":"[[SIM]] hands over a PhET interactive lab card when explaining physics / chemistry (projectiles, circuits, molecular shapes…), and she can tap it open and tweak the parameters herself",
"[[TASK]] 把查资料、核对、翻译这类杂活派给便宜模型后台做，结果随你下一条消息带回（要有 DeepSeek key 或 Gemini 才注入":"[[TASK]] hands chores like looking things up, checking and translating to a cheaper model in the background, and the result comes back with your next message (only injected with a DeepSeek key or Gemini",
"[[ALBUM]] 它自己挑你发的照片收进相册、写第一印象；[[PHOTO]] 聊着聊着把以前的照片翻出来（目录随相册变长":"[[ALBUM]] it picks photos you sent into the album on its own and writes a first impression; [[PHOTO]] digs up old photos mid-conversation (the index grows with the album",
"[[HIDE_LETTER]] 在你标过的地点埋一张纸条，你到了那儿打个卡才拆得开，找到之前正文谁都看不到（地点多了提示跟着变长":"[[HIDE_LETTER]] buries a note at a place you've marked, which can only be opened by checking in when you get there; until found, nobody can see the text (the prompt grows as places pile up",
"[[WISH]] 把你随口说想要的东西悄悄记进本子，你看不到写了什么；[[WISH_OPEN]] 挑个时候翻一页给你（记多了提示跟着变长":"[[WISH]] quietly writes things you casually say you want into the book, and you can't see what it wrote; [[WISH_OPEN]] picks a moment to show you a page (the prompt grows as entries pile up",
