"按住输入栏的「按住 说话」录音，松手直接发一条真语音消息——转写文字默认收起，点「转文字」才展开，AI 读的就是这段文字。语音通话也用这里的设置":"Hold \"Hold to talk\" on the input bar to record, and release to send a real voice message. The transcript is collapsed by default; tap \"Transcribe\" to expand it, and that text is what the AI reads. Voice calls use these settings too",
"转写服务":"Transcription service",
"给「＋ → 语音通话」那块界面换张壁纸。和聊天背景一样：贴图片链接，或从本地选（本地图存 Base64，建议别太大":"Set a wallpaper for the \"+ → Voice call\" screen. Same as the chat background: paste an image link, or pick from local (local images are stored as Base64, so keep them small",
"清除壁纸":"Clear wallpaper",
"壁纸模糊":"Wallpaper blur",
"一起看的时候，它会挑精彩/好笑/虐的地方自己插一句（你在说话、它在说话时不插；多数时候它会选择安静）。这里是频率上限":"When watching together, it picks the exciting / funny / heartbreaking moments to chime in on its own (not while you or it are speaking; most of the time it chooses to stay quiet). This is the frequency cap",
"它说话时你直接开口就能打断（先停一下听听是不是你在说；「嗯」「对」这类附和它会接着说，「等等」「不对」才真停）。外放回声大，要说得更响更久才算":"You can interrupt by just speaking while it talks (it pauses first to check if it's you; backchannels like \"mm\" or \"yeah\" it keeps going through, only \"wait\" or \"no\" really stop it). Speaker echo is loud, so you have to speak louder and longer for it to count",
"你十来秒不说话时，它会自己决定要不要开口说一句（多数时候它该安静陪着；开口两次你都没回就不再说了":"When you've been quiet for about ten seconds, it decides for itself whether to say something (most of the time it should just stay quietly with you; after two tries with no reply from you, it stops",
