"语气跟着生命体征和这句话本身走（开心 / 难过 / 轻声 / 慢慢说…）。在电脑显卡上跑： 第一次要先加载模型、等得久一点，十分钟没人用会自己关掉把显存还回去；没装或跑不起来时自动换回 Edge 的男声。 换声音：往":"Tone follows the vitals and the sentence itself (happy / sad / soft / slow…). Runs on your computer's GPU: the first time it has to load the model, so it takes a bit longer, and after ten minutes unused it shuts itself down to give the VRAM back; if it isn't installed or can't run, it falls back to Edge's male voice automatically. To add a voice: in",
