"（1、2、4、7、15 天、1 个月……）排复习：认识往后走一格，模糊退一格，不认识回起点；答完就告诉你下次哪天见，列表里点开一个词能看到它走到了哪个节点。复习词没认出来的过几张再考一次，熟一点的会轮换成选意思和拼写。「✓ 标熟」随时能点，以后不再出现（列表里可以取消）。想整本从头来，面板最下面有「全部标成没学过」：只清进度，例句、中文和笔记都留着，打卡天数也不断。答完会露出词根词缀、另外几句例句和你写的笔记，笔记在刷卡时点「📝 写笔记」或者在列表里点开那个词写。电脑上可以用 1 2 3 / 方向键作答，空格重播发音，回车下一个。没有到期的也能「提前刷」随机抽 20 张。刷的结果和聊天里答题共用同一套进度，AI 下一轮就知道你刚背过哪些词":"(1, 2, 4, 7, 15 days, 1 month…) scheduled reviews: a word you know moves one step forward, a fuzzy one steps back, and one you don't know goes back to the start; after each answer you're told when you'll see it next, and opening a word in the list shows which step it's on. A review word you didn't recognize comes back a few cards later, and the more familiar ones rotate into picking the meaning and spelling. \"✓ Mark known\" can be tapped any time and the word won't show up again (you can undo it in the list). To start a whole book over, there's \"Mark all as unlearned\" at the bottom of the panel: it only clears progress, while example sentences, Chinese, and notes stay, and your check-in streak isn't broken. After answering you'll see roots and affixes, more example sentences, and your own notes; write a note by tapping \"📝 Write note\" during a card or by opening the word in the list. On the computer you can answer with 1 2 3 / arrow keys, press Space to replay the pronunciation and Enter for the next one. Even with nothing due you can \"Review early\" with 20 random cards. Results here share the same progress as quizzes in chat, so the AI knows next round which words you just studied",
