"思考力度（effort）：越高想得越深、越慢、越费额度。和左边的「思考链」是两件事 —— 这个管想多深，那个管想完给不给你看。4.6 及更老的型号没有「超高」，会按「高」发；Haiku / Sonnet 4.5 不认这个参数，选了也不传":"Thinking effort: the higher it is, the deeper, slower, and more quota-hungry the thinking. This is separate from Reasoning chain on the left: this sets how deeply it thinks, that one sets whether you get to see it. Models 4.6 and older have no Extra high and send High instead; Haiku / Sonnet 4.5 don't support this parameter, so it isn't sent even if selected",
"把 Claude Code 的私人记忆（你的画像、项目背景）注入订阅 Claude 的系统提示":"Inject Claude Code's private memory (your profile, project background) into the Subscription Claude system prompt",
"电脑操控模式：让订阅 Claude 用 Bash/文件工具真的在电脑上执行（编程、跑命令）。给的是电脑完全执行权，谨慎开启":"Computer control mode: lets Subscription Claude actually execute things on the computer with Bash/file tools (coding, running commands). This grants full execution access to the computer, so enable with care",
"浏览器：让订阅 Claude 操作那个专用 Chrome —— 就是登录着你小红书的那一个，不是干净的新窗口。它能看能翻能点；发东西之前它会先问你，但那道闸只是它自己，GranCyan 的每日额度管不到这条路。和电脑操控互相独立，可以只开这个":"Browser: lets Subscription Claude operate that dedicated Chrome, the one logged in to your Xiaohongshu, not a clean new window. It can look, scroll, and click; it asks you before posting anything, but that gate is only itself, and GranCyan's daily quota doesn't cover this route. Independent of Computer control, so you can turn on just this one",
"偷看屏幕：你在用电脑、这边又安静着的时候，它偶尔会截一张你的屏幕，看看你在忙什么然后随口说一句。前台是 GranCyan 自己时不拍。右键 = 3 秒后来一次（留时间切窗口，且不受黑名单限制":"Peek at screen: when you're on the computer and it's quiet here, it'll occasionally grab a screenshot to see what you're up to and drop a casual remark. Doesn't shoot while GranCyan itself is in the foreground. Right-click = one shot after 3 seconds (gives you time to switch windows, and ignores the blocklist",
"额度":"Quota",
"CC记忆":"CC memory",
"选择订阅 GPT 使用的模型":"Choose the model Subscription GPT uses",
"思考深度（Codex 的 reasoning effort）。和左边那个「思考链」是两件事：这个管它想多久，那个管想完了给不给你看。越深越慢越费额度":"Thinking depth (Codex's reasoning effort). Separate from Reasoning chain on the left: this sets how long it thinks, that one sets whether you get to see it. Deeper means slower and more quota",
"电脑操控模式：让订阅 GPT/Codex 在电脑上读写项目、运行命令。给的是电脑执行权，谨慎开启":"Computer control mode: lets Subscription GPT/Codex read and write projects and run commands on the computer. This grants execution access to the computer, so enable with care",
"选择 Gemini 模型。免费层里只有 Flash 系列能随便聊：Pro 系列配额极小（基本一发就 429），出图那两个免费层一次都不给（要给 Google 项目开结算":"Choose a Gemini model. On the free tier only the Flash series is fine for chatting: Pro series quotas are tiny (basically a 429 right away), and the two image-generation models get nothing at all on the free tier (you'd need to enable billing on the Google project",
"思考深度。选「不想」＝不给你看思考链（想多深交给模型自己定，因为有的模型不吃最低档）；其余几档都会把思考摘要一起发过来":"Thinking depth. Choosing \"None\" = no reasoning chain shown (how deep it thinks is left to the model, since some models don't accept the lowest level); every other level sends the thinking summary along",
"让 Gemini 自己上网查（google_search）。和右边那个「🔍 联网搜索」不是一回事：那个是 GranCyan 先替它搜好塞进去，这个是它自己决定查不查、查什么":"Let Gemini search the web itself (google_search). Not the same as 🔍 Web search on the right: that one has GranCyan search first and feed in the results, while here Gemini decides whether to search and what for",
"切换订阅 GPT：用电脑上的 Codex CLI 跑，走订阅额度":"Switch to Subscription GPT: runs through the Codex CLI on the computer, using subscription quota",
"切换 Gemini：直连 Google，不走本机 CLI。没有电脑操控、没有会话续传（每轮重发历史），但模型多、上下文一百万、还能出图":"Switch to Gemini: connects straight to Google, not through the local CLI. No Computer control and no session resume (history is resent every round), but more models, a million tokens of context, and image generation",
