"它怎么看到这些：只在有新鲜事时随你的下一条消息带过去一次——刚从别的 App 回来、每两小时一份今天的时长、换了地方。没有新东西就什么都不加。 精确坐标不出手机系统那层，提示词里只有城市和区，查天气只给到 0.1°（约 11 公里）。这些只存在这台手机里，不上云":"How it sees these: only when there's something new, and sent once along with your next message: just came back from another app, a daily usage summary every two hours, or a change of place. If there's nothing new, nothing is added. Exact coordinates never leave the phone's system layer; the prompt only has the city and district, and weather lookups only get 0.1° (about 11 km). All of this stays on this phone and never goes to the cloud",
