"，见 README）":", see README)",
"空对话页的极光":"Aurora on the empty chat page",
"晨间刚醒、困意":"Just woken up in the morning, still sleepy",
"表情包由作者手绘 ✍️":"Stickers hand-drawn by the author ✍️",
"还没有名字哦（例如：小明）":"No name yet (e.g. Alex)",
"生活：今日小票 / 月历 / 纪念日卡 / 约定":"Life: today's receipt / calendar / anniversary card / promises",
