"早安，今天也慢慢来":"Good morning, take it slow today",
"上午好，今天想做点什么":"Good morning, what shall we do today",
"中午好，记得吃饭":"Good afternoon, don't forget to eat",
"下午好，歇一会儿也没关系":"Good afternoon, it's fine to take a break",
