"设置中心 → 表情包 → 填入 Giphy API Key（":"Settings → Stickers → enter a Giphy API Key (",
"设置中心 → 记忆 → 开启\"自动记忆提取\"（需 API Key），AI 主动总结对话精华":"Settings → Memory → enable \"Auto memory extraction\" (requires API Key); the AI proactively summarizes conversation highlights",
"在这里开始聊天吧 ‿︵‿":"Start chatting here ‿︵‿",
"请先在 设置 → 表情包 中填写 Giphy API Key":"Please enter a Giphy API Key in Settings → Stickers first",
"需要先在 设置 → 表情包 中填写":"First, in Settings → Stickers, enter a",
"给AI发送消息…":"Message the AI…",
"思考默认糊着、选不中（只是界面显示，不进提示词）；关掉这项＝思考一直明着":"Reasoning is blurred and unselectable by default (display only, never added to the prompt); turn this off and reasoning stays visible",
"公开记忆只读（写入权在你手里）/ [[SELF_MEM_SET]]":"Public memory is read-only (you hold the write access) / [[SELF_MEM_SET]]",
"需要：电脑端设好 GRANCYAN_BAND_DB_REMOTE 并运行 server.js ＋ 手机 ADB 已连接 ＋ Gadgetbridge 在后台运行":"Requires: GRANCYAN_BAND_DB_REMOTE set on the computer with server.js running + phone connected via ADB + Gadgetbridge running in the background",
"城市或县，例如：广州、淳安县、Berlin":"City or county, e.g. Guangzhou, Chun'an County, Berlin",
"你":"You",
"来吧，别怪我收租不留情噢":"Come on, don't blame me for showing no mercy when I collect rent",
"停机坪见。我可不打算让你先起飞":"See you on the tarmac. I'm not about to let you take off first",
"开":"On",
"星空":"Starry sky",
