"示例画：月亮和慢慢飘过的云":"Sample painting: the moon and slowly drifting clouds",
"示例画：一片会闪的星空，偶尔有流星划过。删掉就不会再出现":"Sample painting: a twinkling starry sky with the occasional shooting star. Once deleted, it won't come back",
"走订阅：用电脑上的 agy（Antigravity CLI）吃 Google AI Pro 订阅，不要 API key；只有 3.8 Flash（深度选浅/中/深＝low/medium/high 三档），没有自己联网，第一个字要等十来秒。走 key：直连 Google API，模型多、快，但吃 key 的额度。":"Subscription: uses agy (Antigravity CLI) on your computer with your Google AI Pro subscription, no API key needed; only 3.8 Flash (depth light/medium/deep = low/medium/high), no web access of its own, and the first word takes ten-odd seconds. Key: connects straight to the Google API, more models and faster, but uses your key's quota.",
"思考链：要不要把思考摘要显示出来。「关」就不要摘要；新型号想不想由它自己决定。":"Reasoning: whether to show a reasoning summary. \"Off\" means no summary; newer models decide for themselves whether to think.",
